function trasforma(input){
  var s = String(input.Totale || '').replace(/€|EUR|\s/g, '');
  if (!s) return { totale: null };
  var n = parseFloat(s.replace(/\./g, '').replace(',', '.'));
  return { totale: Math.round(n * 100) / 100 };
}

