def trasforma(campi):
    s = str(campi.get('Totale') or '').replace('€', '').replace('EUR', '').replace(' ', '')
    if not s:
        return {'totale': None}
    return {'totale': round(float(s.replace('.', '').replace(',', '.')), 2)}
